#!/usr/bin/env python3
"""Read-only target/physical-event join of the hash-verified c189 metadata archive."""
import pathlib,json,hashlib,collections,datetime,math
R=pathlib.Path('/workspace/poe-pilot/migration-20261028/paper-second-readback/artifact');O=pathlib.Path(__file__).resolve().parent
E=[json.loads(x)for x in(R/'segments/0/selected-events.ndjson').read_text().splitlines()]
rows=lambda k:[e for e in E if e['kind']==k]
ref=lambda e:{'file':e['sourceFile'],'line':e['sourceLine'],'sha256':e['sourceLineSha256']}
quant=lambda a:{'count':len(a),'minimum':min(a)if a else None,'p50':sorted(a)[math.ceil(.5*len(a))-1]if a else None,'p95':sorted(a)[math.ceil(.95*len(a))-1]if a else None,'maximum':max(a)if a else None}
starts={e['data']['id']:e for e in rows('component-physical-start')};ends={e['data']['id']:e for e in rows('component-physical-settled')};http={e['data']['id']:e for e in rows('http-lifecycle-timing')};timeouts={e['data']['id']:e for e in rows('component-physical-timeout')}
miss={(e['data']['mint'],e['data']['windowEndAt']):e for e in rows('native-predictive-window-expired')};summaries={(e['data']['mint'],e['data']['windowEndAt']):e for e in rows('native-audit-dispatch-summary')};retire=rows('native-candidate-retired');cases=[]
