result={'source':json.loads((R/'final-status.json').read_text())['source'],'archiveScope':'allowlisted metadata; no raw full market replay','unavailableAuditTargets':20,'expiredTargetsSubsetOfUnavailable':14,'additionalExpiredTargets':0,'selectedWithoutSessionExpiredTargets':0,'thirdFailureRetirementsWithoutLaterExpiredTarget':6,'failedPageNumbers':dict(collections.Counter(p['page']for p in failed)),'zeroCapturedNotificationTargets':sum(c['capturedNotificationRows']==0 for c in cases),'lastDispatchReadyCandidates':dict(collections.Counter(summaries[(c['mint'],c['windowEndAt'])]['data']['lastState']['context']['readyCandidates']for c in cases)),'failedHeadersAbsent':20,'failedResponseBytes':0,'firstReadyToFirstPhysicalMs':quant([c['pages'][0]['physicalStartedAt']-c['firstReadyAt']for c in cases]),'failedPhysicalEnqueueToStartMs':quant([p['enqueuedToStartMs']for p in failed]),'timeoutCallbackLatenessMs':quant([p['timeoutCallbackLatenessMs']for p in failed]),'settlementAfterTimeoutMs':quant([p['settlementAfterTimeoutMs']for p in failed]),'unusedDecisionRunwayAtFailureMs':quant([c['unusedDeadlineRunwayAtFailureMs']for c in cases]),'cases':cases,'interpretation':['Every expiration correctly means no validated decision by the current bucket cutoff. It is not an additional failure beyond the matched unavailable target.','These requests were dispatched with substantial target runway and failed before the original decision deadline; no audit dispatch starvation or selected-without-session miss was demonstrated here.','All20 failed history requests lacked headers and response bytes. Provider/backend, network, dispatcher/connection behavior and latency beyond the1.5s cutoff remain unresolved; this does not establish provider rate saturation.','Six pools each accumulated three consecutive page1 failures then immediate recoverable retirement. Two other failed targets completed page1 and then timed out on page2.','Successful evidence was unavailable, not optional diagnostics proven irrelevant. No observation window can be certified merely by renaming these misses.'],'input':{'file':'segments/0/selected-events.ndjson','bytes':(R/'segments/0/selected-events.ndjson').stat().st_size,'sha256':hashlib.sha256((R/'segments/0/selected-events.ndjson').read_bytes()).hexdigest()}}
(O/'cases.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items()if k not in ['cases','interpretation']}))
